/*!
 * \file   tests/LoadGenericParallelMaterialPropertyTest.cxx
 * \brief  This file tests the loading of material properties generated by
 * the `generic-parallel` interface of `MFront`, and checks that the types
 * declared by `MGIS` are copies of the ones declared by `TFEL`.
 *
 * usage: LoadGenericParallelMaterialPropertyTest generic_parallel_library
 *        generic_library invalid_library
 * \date   24/10/2026
 * \copyright Use, modification and distribution are subject
 * to one of the following licences:
 * - GNU Lesser General Public License (LGPL), Version 3.0. (See accompanying
 *   file LGPL-3.0.txt)
 * - CECILL-C,  Version 1.0 (See accompanying files
 *   CeCILL-C_V1-en.txt and CeCILL-C_V1-fr.txt).
 */

#include <array>
#include <cmath>
#include <cstddef>
#include <cstdlib>
#include <iostream>
#include <string>
#include <exception>
#include <string_view>
#include <type_traits>
#include "MGIS/MaterialProperty/MaterialProperty.hxx"
#include "MFront/GenericParallelMaterialProperty/MaterialProperty.h"

// copies of the types of `TFEL`: same version, same sizes, same members at
// the same offsets
static_assert(MGIS_MP_GENERIC_PARALLEL_API_VERSION == MFRONT_GPMP_API_VERSION);
static_assert(std::is_same_v<mgis_real, mfront_gmp_real>);
static_assert(sizeof(mgis_size_type) == sizeof(mfront_gmp_size_type));
static_assert(std::is_same_v<mgis_gp_AbstractBackendExecutionPolicy,
                             mfront_gp_AbstractBackendExecutionPolicy>);
static_assert(static_cast<int>(MGIS_MATERIALPROPERTY_NONE_POLICY) ==
              static_cast<int>(GENERIC_MATERIALPROPERTY_NONE_POLICY));
static_assert(static_cast<int>(MGIS_MATERIALPROPERTY_WARNING_POLICY) ==
              static_cast<int>(GENERIC_MATERIALPROPERTY_WARNING_POLICY));
static_assert(static_cast<int>(MGIS_MATERIALPROPERTY_STRICT_POLICY) ==
              static_cast<int>(GENERIC_MATERIALPROPERTY_STRICT_POLICY));
#define MGIS_CHECK_SIZE(T1, T2) \
  static_assert(sizeof(mgis_mp_##T1) == sizeof(mfront_gpmp_##T2))
#define MGIS_CHECK_MEMBER(T1, T2, m) \
  static_assert(offsetof(mgis_mp_##T1, m) == offsetof(mfront_gpmp_##T2, m))
MGIS_CHECK_SIZE(BatchStatistics, Statistics);
MGIS_CHECK_MEMBER(BatchStatistics, Statistics, number_of_failures);
MGIS_CHECK_MEMBER(BatchStatistics, Statistics, first_failure);
MGIS_CHECK_MEMBER(BatchStatistics, Statistics, number_of_unreliable_results);
MGIS_CHECK_MEMBER(BatchStatistics, Statistics, first_unreliable_result);
MGIS_CHECK_SIZE(BatchConstField, ConstField);
MGIS_CHECK_MEMBER(BatchConstField, ConstField, values);
MGIS_CHECK_MEMBER(BatchConstField, ConstField, point_stride);
MGIS_CHECK_SIZE(BatchField, Field);
MGIS_CHECK_MEMBER(BatchField, Field, values);
MGIS_CHECK_MEMBER(BatchField, Field, point_stride);
MGIS_CHECK_SIZE(BatchData, BatchData);
MGIS_CHECK_MEMBER(BatchData, BatchData, number_of_points);
MGIS_CHECK_MEMBER(BatchData, BatchData, output);
MGIS_CHECK_MEMBER(BatchData, BatchData, arguments);
MGIS_CHECK_MEMBER(BatchData, BatchData, number_of_arguments);
MGIS_CHECK_MEMBER(BatchData, BatchData, out_of_bounds_policy);
MGIS_CHECK_MEMBER(BatchData, BatchData, statuses);
MGIS_CHECK_MEMBER(BatchData, BatchData, statistics);
MGIS_CHECK_MEMBER(BatchData, BatchData, execution_policy);
MGIS_CHECK_SIZE(BatchOutputStatus, OutputStatus);
MGIS_CHECK_MEMBER(BatchOutputStatus, OutputStatus, status);
MGIS_CHECK_MEMBER(BatchOutputStatus, OutputStatus, number_of_failures);
MGIS_CHECK_MEMBER(BatchOutputStatus, OutputStatus, first_failure_index);
MGIS_CHECK_MEMBER(BatchOutputStatus,
                  OutputStatus,
                  number_of_unreliable_results);
MGIS_CHECK_MEMBER(BatchOutputStatus,
                  OutputStatus,
                  first_unreliable_result_index);
MGIS_CHECK_MEMBER(BatchOutputStatus, OutputStatus, bounds_status);
MGIS_CHECK_MEMBER(BatchOutputStatus, OutputStatus, msg);

static bool success = true;

static bool check(const bool b, const std::string_view msg) {
  if (!b) {
    success = false;
    std::cerr << msg << '\n';
  }
  return b;
}

//! \brief description and evaluation of a material property on a batch
static void test1(const std::string& gp_library,
                  const std::string& generic_library) {
  using namespace mgis;
  using namespace mgis::material_property;
  const auto mp = load(gp_library, "MaterialPropertyBoundCheck");
  check(isGenericParallelMaterialProperty(mp), "batch functions expected");
  check(mp.fct == nullptr, "no function of a point expected");
  check(mp.batch_report_fct != nullptr, "report function expected");
  check(mp.mfront_interface == "GenericParallel", "invalid interface");
  check(mp.batch_api_version == MGIS_MP_GENERIC_PARALLEL_API_VERSION,
        "invalid version");
  check(mp.backend == "stlpar", "invalid backend");
  check(mp.memory_space == "host", "invalid memory space");
  check(mp.execution_policy == "stlpar", "invalid execution policy");
  check(mp.output == "YoungModulus", "invalid output");
  check((mp.inputs.size() == 1) && (mp.inputs[0] == "Temperature"),
        "invalid inputs");
  // the third temperature is out of the bounds [200:300]
  const auto T = std::array<real, 4u>{250, 280, 100, 300};
  auto E = std::array<real, 4u>{};
  auto statuses = std::array<int, 4u>{12, 12, 12, 12};
  const auto args = std::array<BatchConstField, 1u>{
      BatchConstField{.values = T.data(), .point_stride = 1}};
  auto d =
      BatchData{.number_of_points = 4,
                .output = BatchField{.values = E.data(), .point_stride = 1},
                .arguments = args.data(),
                .number_of_arguments = 1,
                .out_of_bounds_policy = MGIS_MATERIALPROPERTY_NONE_POLICY,
                .statuses = statuses.data(),
                .statistics = nullptr,
                .execution_policy = nullptr};
  // same values as the function of the `generic` interface
  const auto g = load(generic_library, "MaterialPropertyBoundCheck");
  check(!isGenericParallelMaterialProperty(g), "no batch functions expected");
  check((g.fct != nullptr) && (g.batch_api_version == 0) && g.backend.empty(),
        "invalid description of a material property of the generic interface");
  auto s = BatchOutputStatus{};
  check(mp.batch_fct(&s, &d) == 0, "evaluation failed");
  check(s.status == 0, "invalid output status");
  for (std::size_t i = 0; i != T.size(); ++i) {
    auto gs = OutputStatus{};
    const auto Eg = g.fct(&gs, &T[i], 1, MGIS_MATERIALPROPERTY_NONE_POLICY);
    check(std::abs(E[i] - Eg) <= 1e-14 * std::abs(Eg),
          "invalid value at point " + std::to_string(i));
    check(statuses[i] == gs.status,
          "invalid status at point " + std::to_string(i));
  }
  // strict policy, statistics given by the calling code: the evaluation
  // only reports the errors of the batch and the report function gives the
  // result
  auto statistics = BatchStatistics{};
  initializeBatchStatistics(statistics);
  d.out_of_bounds_policy = MGIS_MATERIALPROPERTY_STRICT_POLICY;
  d.statistics = &statistics;
  check(mp.batch_fct(&s, &d) == 0, "invalid status of the batch");
  const auto r = mp.batch_report_fct(&s, &statistics);
  check(r < 0, "the evaluation shall fail at the third point");
  check((s.number_of_failures == 1) && (s.first_failure_index == 2),
        "invalid report");
  check((statuses[0] == 0) && (statuses[1] == 0) && (statuses[2] < 0) &&
            (statuses[3] == 0),
        "invalid statuses of the points");
}

//! \brief material properties which must be refused
static void test2(const std::string& library) {
  using namespace mgis::material_property;
  auto check_refused = [&library](const std::string& n,
                                  const std::string_view expected) {
    try {
      load(library, n);
      check(false, "material property '" + n + "' shall be refused");
    } catch (std::exception& e) {
      check(std::string_view{e.what()}.find(expected) != std::string_view::npos,
            "unexpected message for '" + n + "': " + e.what());
    }
  };
  check_refused("UnsupportedVersion", "unmatched version");
  check_refused("InvalidMemorySpace", "invalid memory space 'nowhere'");
  check_refused("NoVersion", "is not supported");
}

int main(const int argc, const char* const* argv) {
  if (argc != 4) {
    std::cerr << "usage: " << argv[0]
              << " generic_parallel_library generic_library invalid_library\n";
    return EXIT_FAILURE;
  }
  try {
    test1(argv[1], argv[2]);
    test2(argv[3]);
  } catch (std::exception& e) {
    std::cerr << e.what() << '\n';
    return EXIT_FAILURE;
  }
  return success ? EXIT_SUCCESS : EXIT_FAILURE;
}  // end of main
